 12\n)\n\nkras_samples <- substr(\n  unique(maf_kras$Tumor_Sample_Barcode[maf_kras$Hugo_Symbol == \"KRAS\"]),\n  1,\n  12\n)\n\nclinical_egfr <- clinical[\n  substr(clinical$submitter_id, 1, 12) %in% egfr_samples,\n]\n\nclinical_kras <- clinical[\n  substr(clinical$submitter_id, 1, 12) %in% kras_samples,\n]","metadata":{"trusted":true,"execution":{"iopub.status.busy":"2026-03-03T12:38:28.546185Z","iopub.execute_input":"2026-03-03T12:38:28.549652Z","iopub.status.idle":"2026-03-03T12:38:28.768586Z","shell.execute_reply":"2026-03-03T12:38:28.766543Z"}},"outputs":[],"execution_count":13},{"cell_type":"code","source":"nrow(clinical)         # All LUAD\nnrow(clinical_egfr)    # EGFR-mutant\nnrow(clinical_kras)    # KRAS-mutant","metadata":{"trusted":true},"outputs":[{"output_type":"display_data","data":{"text/html":"585","text/markdown":"585","text/latex":"585","text/plain":"[1] 585"},"metadata":{}}],"execution_count":1},{"cell_type":"code","source":"list.files(\"/kaggle/input\", recursive = TRUE)","metadata":{"trusted":true,"execution":{"iopub.status.busy":"2026-03-02T09:10:07.920649Z","iopub.execute_input":"2026-03-02T09:10:07.959931Z","iopub.status.idle":"2026-03-02T09:10:08.008104Z","shell.execute_reply":"2026-03-02T09:10:08.005853Z"}},"outputs":[{"output_type":"display_data","data":{"text/html":"<style>\n.list-inline {list-style: none; margin:0; padding: 0}\n.list-inline>li {display: inline-block}\n.list-inline>li:not(:last-child)::after {content: \"\\00b7\"; padding: 0 .5ex}\n</style>\n<ol class=list-inline><li>'tcga-lecture/TCGA_BRCA_survival.rds'</li><li>'tcga-lecture/TCGA_PCPG_expression.rds'</li></ol>\n","text/markdown":"1. 'tcga-lecture/TCGA_BRCA_survival.rds'\n2. 'tcga-lecture/TCGA_PCPG_expression.rds'\n\n\n","text/latex":"\\begin{enumerate*}\n\\item 'tcga-lecture/TCGA\\_BRCA\\_survival.rds'\n\\item 'tcga-lecture/TCGA\\_PCPG\\_expression.rds'\n\\end{enumerate*}\n","text/plain":"[1] \"tcga-lecture/TCGA_BRCA_survival.rds\"  \n[2] \"tcga-lecture/TCGA_PCPG_expression.rds\""},"metadata":{}}],"execution_count":1},{"cell_type":"markdown","source":"## Survival Analysis","metadata":{}},{"cell_type":"code","source":"library(dplyr)","metadata":{"trusted":true,"execution":{"iopub.status.busy":"2025-12-19T10:52:12.872472Z","iopub.execute_input":"2025-12-19T10:52:12.874205Z","iopub.status.idle":"2025-12-19T10:52:13.068103Z","shell.execute_reply":"2025-12-19T10:52:13.065981Z"}},"outputs":[],"execution_count":null},{"cell_type":"code","source":"clinical <- readRDS(file = \"/kaggle/working/Downloads/TCGA_LUAD_survival.rds\")\n\n\n# create gene column\n\nhead(clinical)\n\nsurvival_data <- clinical %>% select(submitter_id,vital_status, days_to_death,\n                   days_to_last_follow_up,\n                   age_at_diagnosis,\n                   ajcc_pathologic_stage) %>%\n    filter(ajcc_pathologic_stage %in% c(\"Stage IIA\", \"Stage IIB\")) %>%\n    mutate(\n        time = ifelse(vital_status == \"Alive\",\n                     days_to_last_follow_up,\n                     days_to_death),\n        status = ifelse(vital_status == \"Dead\",1,0),\n        age_years = round(age_at_diagnosis / 365,0)\n    )\n\nhead(survival_data)\nsummary(survival_data)\n\nsurvival_data$ajcc_pathologic_stage <- as.factor(survival_data$ajcc_pathologic_stage)\n\n# conduct the survival analysis (Kaplan Meier)\nfit <- survfit(Surv(time,status) ~ strata(ajcc_pathologic_stage), data = survival_data)   # change to strata(gene column)\n\nsummary(fit)\n\noptions(repr.plot.width = 12, repr.plot.height = 12)\nautoplot(fit) + theme_minimal(base_size = 18)\n\n\n# Create a Cox-proportional hazards model\ncox_model <- coxph(Surv(time,status) ~ ajcc_pathologic_stage + age_years, data = survival_data)\n\nsummary(cox_model)\n\nggforest(cox_model, data = survival_data)\n\nnrow(clinical)\n","metadata":{"trusted":true,"execution":{"iopub.status.busy":"2026-03-02T10:07:14.522931Z","iopub.execute_input":"2026-03-02T10:07:14.524566Z","iopub.status.idle":"2026-03-02T10:07:16.172