ion\n\n\nLoading required package: ggplot2\n\nLoading required package: ggpubr\n\n\nAttaching package: ‘survminer’\n\n\nThe following object is masked from ‘package:survival’:\n\n    myeloma\n\n\n","output_type":"stream"}],"execution_count":15},{"cell_type":"code","source":"#create mutation group column\negfr_samples <- substr(unique(maf_data$Tumor_Sample_Barcode[maf_data$Hugo_Symbol == \"EGFR\"]), 1, 12)\nkras_samples <- substr(unique(maf_data$Tumor_Sample_Barcode[maf_data$Hugo_Symbol == \"KRAS\"]), 1, 12)\n\nclinical$patient_id <- substr(clinical$submitter_id, 1, 12)\n\nclinical$mutation_group <- case_when(\n  clinical$patient_id %in% egfr_samples ~ \"EGFR\",\n  clinical$patient_id %in% kras_samples ~ \"KRAS\",\n  TRUE ~ \"LUAD\"\n    )","metadata":{"trusted":true,"execution":{"iopub.status.busy":"2026-03-03T12:49:25.533276Z","iopub.execute_input":"2026-03-03T12:49:25.535650Z","iopub.status.idle":"2026-03-03T12:49:25.569263Z","shell.execute_reply":"2026-03-03T12:49:25.567010Z"}},"outputs":[],"execution_count":18},{"cell_type":"code","source":"# creating survival dataset\nsurvival_data <- clinical %>%\n  select(submitter_id, mutation_group,\n         vital_status, days_to_death,\n         days_to_last_follow_up,\n         age_at_diagnosis,\n         ajcc_pathologic_stage) %>%\n  filter(ajcc_pathologic_stage %in% c(\"Stage IIA\", \"Stage IIB\")) %>%\n  mutate(\n    time = ifelse(vital_status == \"Alive\",\n                  days_to_last_follow_up,\n                  days_to_death),\n    status = ifelse(vital_status == \"Dead\", 1, 0),\n    age_years = round(age_at_diagnosis / 365, 0)\n  )\n\nsurvival_data$mutation_group <- as.factor(survival_data$mutation_group)","metadata":{"trusted":true,"execution":{"iopub.status.busy":"2026-03-03T12:50:00.851842Z","iopub.execute_input":"2026-03-03T12:50:00.854217Z","iopub.status.idle":"2026-03-03T12:50:01.016957Z","shell.execute_reply":"2026-03-03T12:50:01.015067Z"}},"outputs":[],"execution_count":22},{"cell_type":"code","source